   "title": "Therapy Support Worker - RUH@Home",
   "company": "Royal United Hospitals Bath NHS Foundation Trust",
   "employerType": "Direct",
   "level": "Care",
   "careKind": "Healthcare assistant",
   "nhs": "England",
   "location": "Bath, England",
