   "id": "nhse-C9798-26-0120",
   "title": "Community Healthcare Assistant",
   "company": "Herefordshire and Worcestershire Health and Care NHS Trust",
   "employerType": "Direct",
   "level": "Care",
   "careKind": "Healthcare assistant",
   "nhs": "England",
   "location": "Droitwich Spa, England",
